const socUI={network:'All',view:'All',keyword:'',metric:'impressions'};
const socHash=s=>[...String(s)].reduce((h,c)=>(h*31+c.charCodeAt(0))>>>0,17);
function ensureSocialDemoData(){ops.socialStats=ops.socialStats||{};ops.posts.forEach((p,i)=>{if(!ops.socialStats[p.id]){const h=socHash(p.id);ops.socialStats[p.id]={impressions:1800+h%19000,engagements:60+h%950,sentiment:25+h%62,trend:8+h%140,observedAt:new Date(Date.now()-i*35*60000).toISOString()}}});ops.cases.forEach(c=>{if(!c.aiSentiment)c.aiSentiment={score:({Negative:-82,Concerned:-58,Neutral:4,Positive:78})[c.sentiment]??0,confidence:0.72+(socHash(c.id)%19)/100,source:'Simulated AI classifier; not a live model'}})}
function socScopedPosts(){return visiblePosts().filter(p=>socUI.network==='All'||channelById(p.channel)?.network===socUI.network)}
function socScopedMessages(){return visibleCases().filter(c=>socUI.network==='All'||channelById(c.channel)?.network===socUI.network)}
function socRecentPosts(posts){return posts.filter(p=>['Published','Failed'].includes(p.status)).sort((a,b)=>String(b.history?.at(-1)?.time||ops.socialStats[b.id]?.observedAt||b.created).localeCompare(String(a.history?.at(-1)?.time||ops.socialStats[a.id]?.observedAt||a.created))).slice(0,5)}
function socNextPosts(posts){return posts.filter(p=>p.status==='Scheduled').sort((a,b)=>(a.scheduled||'9999').localeCompare(b.scheduled||'9999')).slice(0,5)}
function socSentimentMean(values){return values.length?Math.round(values.reduce((sum,value)=>sum+value,0)/values.length):null}
function socSevenDays(posts,messages){const eligible=posts.filter(p=>p.status==='Published');return Array.from({length:7},(_,day)=>{let impressions=0,engagements=0;eligible.forEach(p=>{const stat=ops.socialStats[p.id];const weight=[9,11,12,14,15,18,21][day];impressions+=Math.round(stat.impressions*weight/100);engagements+=Math.round(stat.engagements*weight/100)});const sentimentValues=messages.filter((_,i)=>i%7===day).map(c=>c.aiSentiment.score);const date=new Date();date.setDate(date.getDate()-(6-day));return {day:date.toLocaleDateString('en-CA',{timeZone:'America/New_York',weekday:'short'}),date:date.toLocaleDateString('en-CA',{timeZone:'America/New_York'}),impressions,engagements,sentiment:socSentimentMean(sentimentValues)}})}
function socKeywords(messages,posts){const stop=new Set(['the','and','for','this','that','with','from','have','your','our','are','can','you','was','how','what','when','will','does','new','again','thank','thanks','here','there','about','sample','fictional','post','demo','during','through','along','their','them','they','has','been','its','were','not','which']);const counts={};[...messages.map(m=>m.text),...posts.map(p=>p.text)].forEach(text=>{const words=new Set((text.toLowerCase().match(/[a-z]{4,}/g)||[]).filter(w=>!stop.has(w)));words.forEach(w=>counts[w]=(counts[w]||0)+1)});return Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,22)}
const shortNumber=n=>n===null?'—':Math.abs(n)>=1000?(n/1000).toFixed(1)+'K':String(n);
function socChart(days,metric){const values=days.map(d=>d[metric]??0),max=metric==='sentiment'?100:Math.max(...values,1),min=metric==='sentiment'?-100:0;const points=values.map((v,i)=>[45+i*82,160-(v-min)/(max-min)*120]);const labels={impressions:'Impressions',engagements:'Engagements',sentiment:'Average sentiment'};return `<div class="soc-chart" role="img" aria-label="${labels[metric]} across the last seven days; simulated values. See the data table below."><svg viewBox="0 0 590 205" aria-hidden="true"><path d="M45 40H550 M45 100H550 M45 160H550" stroke="currentColor" stroke-opacity=".13" fill="none"/>${metric==='sentiment'?'<path d="M45 100H550" stroke="currentColor" stroke-opacity=".3" stroke-dasharray="4 4"/>':''}<path d="${points.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join(' ')}" fill="none" stroke="var(--soc-line)" stroke-width="3" stroke-linejoin="round"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="var(--soc-line)"><title>${days[i].day}: ${days[i][metric]===null?'No samples':days[i][metric]}</title></circle><text x="${x}" y="190" text-anchor="middle" fill="currentColor" font-size="11">${days[i].day}</text>`).join('')}<text x="5" y="44" fill="currentColor" font-size="10">${shortNumber(max)}</text><text x="5" y="164" fill="currentColor" font-size="10">${min}</text></svg></div>`}
function socPostRow(p,upcoming=false){const c=channelById(p.channel),stat=ops.socialStats[p.id],status=upcoming?(ops.paused?'Paused':connectionState(c)==='Expired'?'Token expired':'Scheduled'):p.status==='Failed'?'Failed':'Healthy';return `<button class="soc-post-row" data-soc-post="${p.id}">${channelAvatar(c)}<span class="soc-post-copy"><strong>${safe(p.title)}</strong><small>${safe(c.name)} · ${c.network}</small><small>${upcoming?(p.scheduled?p.scheduled.replace('T',' · ')+' America/Halifax':'Time not set'):'Last sample check '+timeLabel(stat.observedAt)}</small></span><span class="badge ${status==='Failed'||status==='Token expired'?'fail':status==='Healthy'?'ok':'warn'}">${status}</span></button>`}
renderSOC=function(){ensureSocialDemoData();const posts=socScopedPosts(),messages=socScopedMessages(),days=socSevenDays(posts,messages);const recent=socRecentPosts(posts),next=socNextPosts(posts),negative=messages.filter(m=>m.aiSentiment.score<=-50&&(socUI.view==='All'||m.type===socUI.view)).sort((a,b)=>a.aiSentiment.score-b.aiSentiment.score);const trending=posts.filter(p=>p.status==='Published').sort((a,b)=>ops.socialStats[b.id].engagements-ops.socialStats[a.id].engagements).slice(0,5);const keywords=socKeywords(messages,posts);const impressions=days.reduce((sum,d)=>sum+d.impressions,0),engagements=days.reduce((sum,d)=>sum+d.engagements,0),average=socSentimentMean(messages.map(m=>m.aiSentiment.score));document.querySelector('#main').innerHTML=heading('Social Operation Center','Publishing health, audience conversations and channel performance.',`<span class="sample-label">SIMULATED SOCIAL DATA</span>${isAdmin()?`<button class="btn" data-cmd="stream">${streamTimer?'Ⅱ Pause stream':'▶ Play demo updates'}</button><button class="btn primary" data-cmd="next-update">Next update →</button>`:''}`)+`<div class="soc-control-bar"><label>Network<select id="soc-network">${['All',...networkOptions.map(n=>n.name)].map(n=>`<option ${n===socUI.network?'selected':''}>${n}</option>`)}</select></label><p>Last 7 days · sample snapshots · sentiment −100 (negative) to +100 (positive)</p><span class="badge ${ops.paused?'fail':'ok'}">${ops.paused?'Publishing paused':'Publishing available'}</span>${isAdmin()?`<button class="btn ${ops.paused?'primary':'danger'}" data-cmd="pause-publishing">${ops.paused?'Authorize resume':'Emergency pause'}</button>`:''}</div><div class="soc-source-note">All metrics, delivery checks and AI sentiment scores here are mocked. Counts use your accessible demo records. No platform analytics or live model is connected.</div><div class="grid metrics">${[['Total impressions',shortNumber(impressions),'7-day sample total'],['Total engagement',shortNumber(engagements),'Reactions, comments & shares · sample'],['Average sentiment',average===null?'—':(average>0?'+':'')+average,messages.length+' scored sample conversations'],['Publishing health',recent.filter(p=>p.status==='Published').length+'/'+recent.length,'Healthy among last '+recent.length+' aired attempts']].map(([label,value,caption])=>`<div class="metric"><span class="label">${label}</span><b>${value}</b><span class="delta">${caption}</span></div>`).join('')}</div><div class="soc-two-column"><section class="card"><div class="soc-section-head"><div><h3>Last 5 posts · air status</h3><p>Published and failed delivery attempts</p></div><button class="asset-link" data-soc-content="All">All content →</button></div>${recent.map(p=>socPostRow(p)).join('')||'<p class="ops-muted">No accessible published or failed posts yet.</p>'}</section><section class="card"><div class="soc-section-head"><div><h3>Next 5 posts</h3><p>Ordered by requested publish time</p></div><button class="asset-link" data-soc-content="Scheduled">Schedule →</button></div>${next.map(p=>socPostRow(p,true)).join('')||'<p class="ops-muted">No scheduled posts within your account scope.</p>'}${ops.paused?'<p class="soc-pause-note">Emergency pause blocks every pending demo publication.</p>':''}${can('content.publish')?'<button class="btn" data-cmd="process-queue">Process next demo publication</button>':''}</section></div><section class="card soc-performance"><div class="soc-section-head"><div><h3>Last 7 days · performance</h3><p>Simulated daily distribution, not production analytics</p></div><div class="soc-metric-tabs">${[['impressions','Impressions'],['engagements','Engagement'],['sentiment','Sentiment']].map(([key,label])=>`<button class="${socUI.metric===key?'active':''}" data-soc-metric="${key}">${label}</button>`).join('')}</div></div>${socChart(days,socUI.metric)}<details><summary>View daily values and source</summary><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Impressions</th><th>Engagements</th><th>Average sentiment</th><th>Source</th></tr></thead><tbody>${days.map(d=>`<tr><td>${d.date}</td><td>${d.impressions}</td><td>${d.engagements}</td><td>${d.sentiment===null?'No samples':d.sentiment}</td><td>Simulated snapshot</td></tr>`).join('')}</tbody></table></div></details></section><div class="soc-two-column"><section class="card"><div class="soc-section-head"><div><h3>Angry / negative audience conversations</h3><p>AI-style score ≤ −50 · uncertain, staff review required</p></div><label>Type<select id="soc-message-type">${['All','Comment','Message'].map(t=>`<option ${t===socUI.view?'selected':''}>${t}</option>`)}</select></label></div>${negative.slice(0,5).map(c=>`<button class="soc-message-row" data-soc-message="${c.id}"><span class="soc-sentiment-score">${c.aiSentiment.score}<small>${Math.round(c.aiSentiment.confidence*100)}% demo confidence</small></span><span class="soc-message-copy"><strong>${safe(c.text)}</strong><small>${channelById(c.channel)?.network} · ${c.type==='Message'?'Direct message':'Comment'} · ${safe(c.author)}</small><small>Responding: ${safe(accessUsers.find(u=>u.id===c.owner)?.name||'Not assigned')} · ${c.status==='Resolved'?'Reviewed':'Awaiting response'}</small></span></button>`).join('')||'<p class="ops-muted">No accessible conversations match this sentiment filter. Inbox permission and channel access are required to view message text.</p>'}<div class="soc-section-footer"><span>${negative.length} matching sample conversations</span>${can('inbox.respond')?'<button class="asset-link" id="soc-open-inbox">Open Inbox & Comments →</button>':''}</div></section><section class="card"><div class="soc-section-head"><div><h3>Highlight keywords</h3><p>Most frequent terms in accessible posts and conversations</p></div></div><div class="soc-keyword-cloud">${keywords.map(([word,count],i)=>`<button data-soc-keyword="${word}" style="font-size:${Math.max(14,29-i*.65)}px" title="${count} sample records">${word}<small>${count}</small></button>`).join('')||'<p class="ops-muted">No keywords available for your account scope.</p>'}</div><p class="ops-muted">Choose a word to inspect matching social content. Frequency is derived from demo text, not a listening provider.</p></section></div><section class="card soc-trending"><div class="soc-section-head"><div><h3>Trending posts</h3><p>Accessible published posts ranked by simulated engagement</p></div><span class="badge">Sample ranking</span></div><div class="soc-trending-grid">${trending.map((p,i)=>`<button class="soc-trend-card" data-soc-post="${p.id}"><div class="soc-trend-image"><img src="${p.mediaUrl||samplePhoto(p.art,500)}" alt="${safe(p.alt)}" loading="lazy" referrerpolicy="no-referrer"><span>#${i+1}</span></div><h4>${safe(p.title)}</h4><p>${channelById(p.channel)?.network} · ${shortNumber(ops.socialStats[p.id].engagements)} engagement</p><strong>↑ ${ops.socialStats[p.id].trend}% sample growth</strong></button>`).join('')||'<p class="ops-muted">Publish a demo post to populate this view.</p>'}</div></section><section class="card" style="margin-top:22px"><div class="soc-section-head"><div><h3>Social update feed</h3><p>Mock audience activity, delivery status and engagement changes</p></div><span class="badge">${streamTimer?'Playing · every 12 seconds':'Paused · advance manually'}</span></div>${(isAdmin()?ops.events.filter(e=>e.action.startsWith('SOC')||e.action.includes('publishing')||e.action.includes('publication')).slice(0,5):[]).map(e=>`<div class="row"><span class="badge">Demo</span><div class="grow"><strong>${safe(e.action)}</strong><small>${safe(e.detail)} · ${timeLabel(e.time)}</small></div></div>`).join('')||'<p class="ops-muted">Select Next update to simulate a social-channel event.</p>'}</section>`;document.querySelector('#soc-network').onchange=e=>{socUI.network=e.target.value;renderWorkspace('soc')};document.querySelector('#soc-message-type').onchange=e=>{socUI.view=e.target.value;renderWorkspace('soc')};document.querySelectorAll('[data-soc-metric]').forEach(b=>b.onclick=()=>{socUI.metric=b.dataset.socMetric;renderWorkspace('soc')});document.querySelectorAll('[data-soc-post]').forEach(b=>b.onclick=()=>openPost(b.dataset.socPost));document.querySelectorAll('[data-soc-content]').forEach(b=>b.onclick=()=>{contentStatus=b.dataset.socContent;contentNetwork=socUI.network;contentSearch='';renderWorkspace('content')});document.querySelectorAll('[data-soc-message]').forEach(b=>b.onclick=()=>{selectedCase=b.dataset.socMessage;inboxState='All';inboxType='All';inboxSentiment='All';inboxOwner='All';inboxSearch='';renderWorkspace('inbox')});document.querySelectorAll('[data-soc-keyword]').forEach(b=>b.onclick=()=>{contentSearch=b.dataset.socKeyword;contentStatus='All';contentNetwork=socUI.network;renderWorkspace('content')});document.querySelector('#soc-open-inbox')?.addEventListener('click',()=>{inboxState='All';inboxSentiment='Negative';inboxType='All';inboxSearch='';renderWorkspace('inbox')});};
nextDemoUpdate=function(){if(!isAdmin())return;ensureSocialDemoData();const index=ops.updateIndex++,channel=assetsData.channels[index%assetsData.channels.length];if(!channel){toast('Add a social channel first.');return}switch(index%4){case 0:ops.cases.unshift({id:'SOC-MESSAGE-'+Date.now(),channel:channel.id,type:index%8===0?'Comment':'Message',text:'I am frustrated that the Route 8 service update was unclear. Where is the accessible boarding stop?',author:'Fictional social follower',sentiment:'Negative',aiSentiment:{score:-88,confidence:.86,source:'Simulated AI classifier'},urgency:'Normal',owner:'',status:'Open',notes:[],draft:'',created:nowISO()});logOps('SOC · new angry audience conversation',channel.network+'; sentiment −88, simulated AI score.');break;case 1:{const post=ops.posts.find(p=>p.status==='Published');if(post){ops.socialStats[post.id].engagements+=120;ops.socialStats[post.id].impressions+=1850;ops.socialStats[post.id].trend+=12;ops.socialStats[post.id].observedAt=nowISO();logOps('SOC · post engagement rising',post.title+'; sample engagement +120, impressions +1,850.')}break}case 2:{const post=ops.posts.find(p=>p.status==='Scheduled');if(post){if(ops.paused){logOps('SOC · scheduled publication blocked','Emergency pause gate retained; '+post.title+' remains scheduled.')}else{post.status='Failed';post.history.push({action:'Mock provider delivery failure',time:nowISO()});ops.socialStats[post.id].observedAt=nowISO();logOps('SOC · mock publication failed',post.title+'; no platform called.')}}break}case 3:{const post=ops.posts.find(p=>p.status==='Published');if(post){ops.socialStats[post.id].observedAt=nowISO();logOps('SOC · published post healthy',post.title+'; simulated delivery check completed.')}break}}saveOps();if(currentPage==='soc'||currentPage==='inbox')renderWorkspace(currentPage)};
renderWorkspace('soc');
